const formPessoa = document.getElementById('form-pessoa');
const inputNome = document.getElementById('nome');
const inputIdade = document.getElementById('idade');
const inputAltura = document.getElementById('altura');
const inputPeso = document.getElementById('peso');
const mensagemDeErro = document.getElementById('erro');
const tabelaPessoas = document.getElementById('tabela-pessoas');

const CHAVE_PESSOAS = 'pessoas';
let codigoContador = 0;
let pessoas = carregarPessoas();

ajustarContadorCodigo();

function calcularImc(peso, altura) {
    return peso / (altura * altura);
    }

    function classificarImc(imc) {
        if (imc < 18.5) {
                return { texto: 'Abaixo do peso', classe: 'bg-abaixo' };
                    } else if (imc < 25) {
                            return { texto: 'Peso normal', classe: 'bg-normal' };
                                } else if (imc < 30) {
                                        return { texto: 'Sobrepeso', classe: 'bg-sobrepeso' };
                                            } else if (imc < 35) {
                                                    return { texto: 'Obesidade Grau I', classe: 'bg-obs1' };
                                                        } else if (imc < 40) {
                                                                return { texto: 'Obesidade Grau II', classe: 'bg-obs2' };
                                                                    } else {
                                                                            return { texto: 'Obesidade Grau III', classe: 'bg-obs3' };
                                                                                }
                                                                                }

                                                                                function formatar(valor, decimais) {
                                                                                    return valor.toLocaleString('pt-BR', {
                                                                                            minimumFractionDigits: decimais,
                                                                                                    maximumFractionDigits: decimais
                                                                                                        });
                                                                                                        }

                                                                                                        function salvar() {
                                                                                                            localStorage.setItem(CHAVE_PESSOAS, JSON.stringify(pessoas));
                                                                                                            }

                                                                                                            function carregarPessoas() {
                                                                                                                const dados = localStorage.getItem(CHAVE_PESSOAS);
                                                                                                                    if (!dados) return [];

                                                                                                                        try {
                                                                                                                                const lista = JSON.parse(dados);
                                                                                                                                        if (Array.isArray(lista)) return lista;
                                                                                                                                            } catch (e) {
                                                                                                                                                    console.error('Erro ao analisar os dados do localStorage', e);
                                                                                                                                                        }
                                                                                                                                                            return [];
                                                                                                                                                            }

                                                                                                                                                            function ajustarContadorCodigo() {
                                                                                                                                                                let maior = 0;
                                                                                                                                                                    pessoas.forEach(p => {
                                                                                                                                                                            if (p.id > maior) {
                                                                                                                                                                                        maior = p.id;
                                                                                                                                                                                                }
                                                                                                                                                                                                    });
                                                                                                                                                                                                        codigoContador = maior;
                                                                                                                                                                                                        }

                                                                                                                                                                                                        function gerarCodigo() {
                                                                                                                                                                                                            return ++codigoContador;
                                                                                                                                                                                                            }

                                                                                                                                                                                                            function validarDados(dados) {
                                                                                                                                                                                                                if (!dados.nome || dados.nome.length < 2) {
                                                                                                                                                                                                                        return 'Informe o nome com no mínimo de duas letras.';
                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                if (!Number.isInteger(dados.idade) || dados.idade < 1 || dados.idade > 120) {
                                                                                                                                                                                                                                        return 'A idade deve ser um número inteiro entre 1 e 120.';
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                if (dados.altura < 0.5 || dados.altura > 2.5) {
                                                                                                                                                                                                                                                        return 'A altura deve estar entre 0.5m e 2.5m.';
                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                if (dados.peso < 2 || dados.peso > 500) {
                                                                                                                                                                                                                                                                        return 'O peso deve estar entre 2kg e 500kg.';
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                return '';
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                function mostrarErro(mensagem) {
                                                                                                                                                                                                                                                                                    mensagemDeErro.textContent = mensagem;
                                                                                                                                                                                                                                                                                        mensagemDeErro.hidden = false;
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                        function limparErro() {
                                                                                                                                                                                                                                                                                            mensagemDeErro.textContent = '';
                                                                                                                                                                                                                                                                                                mensagemDeErro.hidden = true;
                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                function lerFormulario() {
                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                            nome: inputNome.value.trim(),
                                                                                                                                                                                                                                                                                                                    idade: Number(inputIdade.value),
                                                                                                                                                                                                                                                                                                                            altura: Number(inputAltura.value),
                                                                                                                                                                                                                                                                                                                                    peso: Number(inputPeso.value)
                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                        function adicionarPessoa(dados) {
                                                                                                                                                                                                                                                                                                                                            const novaPessoa = {
                                                                                                                                                                                                                                                                                                                                                    id: gerarCodigo(),
                                                                                                                                                                                                                                                                                                                                                            nome: dados.nome,
                                                                                                                                                                                                                                                                                                                                                                    idade: dados.idade,
                                                                                                                                                                                                                                                                                                                                                                            altura: dados.altura,
                                                                                                                                                                                                                                                                                                                                                                                    peso: dados.peso
                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                            pessoas.push(novaPessoa);
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                            function criarCelula(texto) {
                                                                                                                                                                                                                                                                                                                                                                                                const td = document.createElement('td');
                                                                                                                                                                                                                                                                                                                                                                                                    td.textContent = texto;
                                                                                                                                                                                                                                                                                                                                                                                                        return td;
                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                        function criarLinha(pessoa) {
                                                                                                                                                                                                                                                                                                                                                                                                            const tr = document.createElement('tr');
                                                                                                                                                                                                                                                                                                                                                                                                                tr.dataset.id = pessoa.id;

                                                                                                                                                                                                                                                                                                                                                                                                                    const imc = calcularImc(pessoa.peso, pessoa.altura);
                                                                                                                                                                                                                                                                                                                                                                                                                        const classificacao = classificarImc(imc);

                                                                                                                                                                                                                                                                                                                                                                                                                            tr.appendChild(criarCelula(pessoa.nome));
                                                                                                                                                                                                                                                                                                                                                                                                                                tr.appendChild(criarCelula(pessoa.idade));
                                                                                                                                                                                                                                                                                                                                                                                                                                    tr.appendChild(criarCelula(formatar(pessoa.altura, 2) + ' m'));
                                                                                                                                                                                                                                                                                                                                                                                                                                        tr.appendChild(criarCelula(formatar(pessoa.peso, 1) + ' kg'));
                                                                                                                                                                                                                                                                                                                                                                                                                                            tr.appendChild(criarCelula(formatar(imc, 1)));

                                                                                                                                                                                                                                                                                                                                                                                                                                                const tdClassificacao = document.createElement('td');
                                                                                                                                                                                                                                                                                                                                                                                                                                                    const selo = document.createElement('span');
                                                                                                                                                                                                                                                                                                                                                                                                                                                        selo.className = `selo ${classificacao.classe}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            selo.textContent = classificacao.texto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                tdClassificacao.appendChild(selo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tr.appendChild(tdClassificacao);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tdAcoes = document.createElement('td');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const btnExcluir = document.createElement('button');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                btnExcluir.textContent = 'Excluir';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    btnExcluir.style.backgroundColor = '#e74c3c';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btnExcluir.style.color = 'white';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            btnExcluir.style.padding = '5px 10px';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                btnExcluir.style.fontSize = '0.85rem';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        btnExcluir.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                removerPessoa(pessoa.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tdAcoes.appendChild(btnExcluir);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tr.appendChild(tdAcoes);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return tr;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function render() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tabelaPessoas.innerHTML = '';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (pessoas.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const tr = document.createElement('tr');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const td = document.createElement('td');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                td.colSpan = 7;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        td.className = 'vazio';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                td.textContent = 'Nenhuma pessoa cadastrada ainda';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tr.appendChild(td);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tabelaPessoas.appendChild(tr);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                pessoas.forEach(pessoa => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tr = criarLinha(pessoa);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tabelaPessoas.appendChild(tr);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function removerPessoa(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pessoas = pessoas.filter(p => p.id !== id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formPessoa.addEventListener('submit', (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    e.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const dados = lerFormulario();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const erro = validarDados(dados);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (erro !== '') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarErro(erro);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        limparErro();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            adicionarPessoa(dados);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    formPessoa.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inputNome.focus();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            render();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            